function money(value: number) {
  return new Prisma.Decimal(value.toFixed(2));
}

async function seedUnits() {
  const unitNames = Array.from(new Set(ITEM_SEED_ROWS.map((row) => row.unitName)));
  const unitByName = new Map<string, string>();
  let created = 0;
  let updated = 0;

  for (const name of unitNames) {
    const existing = await prisma.unit.findUnique({ where: { name } });
    const unit = await prisma.unit.upsert({
      where: { name },
      update: { isActive: true },
      create: { name, isActive: true },
    });

    unitByName.set(name, unit.id);

    if (existing) {
      updated += 1;
    } else {
      created += 1;
    }
  }

  return { unitByName, created, updated };
}

async function seedCategories() {
  const categoryNames = Array.from(new Set(ITEM_SEED_ROWS.map((row) => row.categoryName)));
  const categoryByName = new Map<string, string>();
  let created = 0;
  let updated = 0;

  for (const name of categoryNames) {
    const existing = await prisma.category.findUnique({ where: { name } });
    const category = await prisma.category.upsert({
      where: { name },
      update: { isActive: true },
      create: { name, isActive: true },
    });

    categoryByName.set(name, category.id);

    if (existing) {
      updated += 1;
    } else {
      created += 1;
    }
  }

  return { categoryByName, created, updated };
}

async function seedItems(categoryByName: Map<string, string>, unitByName: Map<string, string>) {
  let created = 0;
  let updated = 0;

  for (const row of ITEM_SEED_ROWS) {
    const categoryId = categoryByName.get(row.categoryName);
    const unitId = unitByName.get(row.unitName);

    if (!categoryId) {
      throw new Error(`Missing seeded category for item ${row.sku}: ${row.categoryName}`);
    }

    if (!unitId) {
      throw new Error(`Missing seeded unit for item ${row.sku}: ${row.unitName}`);
    }

    const existing = await prisma.product.findUnique({ where: { sku: row.sku } });

    await prisma.product.upsert({
      where: { sku: row.sku },
      update: {
        name: row.name,
        categoryId,
        unitId,
        unitId: null,
        buyingPrice: money(0),
        sellingPrice: money(row.sellingPrice),
        buyingPrice: money(0),
        sellingPrice: money(0),
        isActive: true,
      },
      create: {
        sku: row.sku,
        name: row.name,
        categoryId,
        unitId,
        unitId: null,
        buyingPrice: money(0),
        sellingPrice: money(row.sellingPrice),
        buyingPrice: money(0),
        sellingPrice: money(0),
        isActive: true,
      },
    });

    if (existing) {
      updated += 1;
    } else {
      created += 1;
    }
  }

  return { created, updated };
}

async function main() {
  const units = await seedUnits();
  const categories = await seedCategories();
  const items = await seedItems(categories.categoryByName, units.unitByName);

  console.log("Company/item seed completed from embedded Document item data.");
  console.log(`Item rows read: ${ITEM_SEED_SOURCE.extractedRows}`);
  console.log(`Skipped source rows: ${ITEM_SEED_SOURCE.skippedRows}`);
  console.log(`Duplicate SKU rows given suffix: ${ITEM_SEED_SOURCE.duplicateSkuRows}`);
  console.log(`Categories created: ${categories.created}`);
  console.log(`Categories updated: ${categories.updated}`);
  console.log(`Units created: ${units.created}`);
  console.log(`Units updated: ${units.updated}`);
  console.log(`Items created: ${items.created}`);
  console.log(`Items updated: ${items.updated}`);
}

main()
  .catch((error) => {
    console.error(error);
    process.exitCode = 1;
  })
  .finally(async () => {
    await prisma.$disconnect();
  });